public class MemoryTroubleshootingDemonstration {
    // Simulating a classic JRE memory error via an unbounded local cache
    private static final java.util.Map<String, byte[]> unbondedCache = new java.util.concurrent.ConcurrentHashMap<>();

    public void simulateJreMemoryPressure() {
        int counter = 0;
        while (true) {
            // Allocating heavy byte arrays directly onto the JVM heap
            unbondedCache.put("key-" + (++counter), new byte[1024 * 1024]); // 1MB each
            if (counter % 100 == 0) {
                System.out.println("Allocated " + counter + " MB on JVM Heap.");
            }
        }
    }
}
